def jdump(v): return json.dumps(v, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

def option_metrics(options,key):
    lengths={k:len(str(v).strip()) for k,v in options.items()}; vals=list(lengths.values())
    ratio=max(vals)/max(min(vals),1); dmean=sum(lengths[k] for k in "ABCD" if k!=key)/3
    deviation=abs(lengths[key]-dmean)/max(dmean,1)
    unique=((lengths[key]==min(vals) and vals.count(min(vals))==1) or (lengths[key]==max(vals) and vals.count(max(vals))==1))
    return lengths,ratio,deviation,unique

def main():
    ev=json.loads(EVIDENCE.read_text(encoding="utf-8")); by={x["id"]:x for x in ev["items"]}
    if set(by)!=set(IDS) or len(by)!=50: raise SystemExit("Batch005 evidence scope mismatch")
    con=sqlite3.connect(DB); con.row_factory=sqlite3.Row
    rows={r["question_uid"]:r for r in con.execute("SELECT question_uid,source_id,stem,item_data_json,correct_answer_json,rationale,source_name,source_detail,source_url FROM questions WHERE question_uid BETWEEN 'V2-Q0782' AND 'V2-Q0831' ORDER BY question_uid")}; con.close()
    if set(rows)!=set(IDS): raise SystemExit("Batch005 DB scope mismatch")
    out=[]; failures=[]
    for uid in IDS:
        q=rows[uid]; e=by[uid]; options=json.loads(q["item_data_json"])["options"]; key=json.loads(q["correct_answer_json"])["correct_option"]
        stem=q["stem"]; rationale=q["rationale"]; substantive=False; option_rewrite=False
        if uid in PATCHES:
            p=PATCHES[uid]
            if p["key"]!=key or p["key"]!=e["key"]: failures.append(f"{uid}: correction key mismatch DB={key} evidence={e['key']} patch={p['key']}"); continue
            stem=p["stem"]; options=p["options"]; rationale=p["rationale"]; substantive=True
        elif uid in OPTION_REWRITES:
            if key!=e["key"]: failures.append(f"{uid}: option rewrite key mismatch DB={key} evidence={e['key']}"); continue
            options=OPTION_REWRITES[uid]; option_rewrite=True
        if key!=e["key"]: failures.append(f"{uid}: baseline/evidence key mismatch"); continue
        if set(options)!=set("ABCD") or len({str(v).strip().casefold() for v in options.values()})!=4: failures.append(f"{uid}: invalid options"); continue
        lengths,ratio,dev,unique=option_metrics(options,key)
        if ratio>1.15+1e-12 or dev>0.10+1e-12 or unique: failures.append(f"{uid}: option QC ratio={ratio:.4f} dev={dev:.4f} unique={unique}"); continue
        if not e["source_url"].startswith("https://"): failures.append(f"{uid}: invalid source URL"); continue
        source_detail=f"{e['source_locator']} {e['source_version']} Reviewed 2026-08-15."
        flags=["RULE1_BATCH005_REAL_REAUDIT","SOURCE_LOCATOR_VERSION_CURRENTNESS_VERIFIED","SECOND_PASS_QA_PASS","STRICT_OPTION_LENGTH_ANTI_CUE_QC_PASS"]
        if substantive: flags.append("SUBSTANTIVE_CORRECTION")
        if option_rewrite: flags.append("OPTION_CUE_QC_REWRITE")
        if e.get("authority")=="S": flags.append("DOCUMENTED_SECONDARY_SOURCE_EXCEPTION")
        rank=1+sum(1 for n in lengths.values() if n<lengths[key])
        out.append({"question_uid":uid,"source_id":q["source_id"],"stem":stem,"item_data_json":jdump({"options":options}),"correct_answer_json":jdump({"correct_option":key}),"rationale":rationale,"source_name":q["source_name"],"source_detail":source_detail,"source_url":e["source_url"],"clinical_qa_status":"SOURCE_VERIFIED_2026_RULE1_BATCH005","editorial_priority":"PRODUCTION_CANDIDATE","editorial_flags_json":jdump(flags),"qc":{"question_uid":uid,"lengths_json":jdump(lengths),"min_chars":min(lengths.values()),"max_chars":max(lengths.values()),"max_min_ratio":round(ratio,4),"correct_option":key,"correct_length_rank":rank,"correct_is_extreme":0,"qc_status":"PASS","qc_note":"Rule 1 Batch 005 semantic option/cue QC: max/min <=1.15; correct-option deviation <=10%; correct option is not a unique length extreme; no artificial padding."}})
    if failures: raise SystemExit("\n".join(failures))
    if len(out)!=50: raise SystemExit(f"Expected 50 override items, got {len(out)}")
    OUT.write_text(json.dumps({"version":"2026-08-15-rule1-batch005-real-reaudit","questions":out},ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    print(f"BATCH005_OVERRIDE_BUILT questions=50/50 corrections={sum('SUBSTANTIVE_CORRECTION' in json.loads(x['editorial_flags_json']) for x in out)}/16 option_rewrites={sum('OPTION_CUE_QC_REWRITE' in json.loads(x['editorial_flags_json']) for x in out)}/30 option_qc=50/50")

if __name__=="__main__": main()
